window.MOONLIT_CATALOG={"counts":{"novels":15,"comics":2,"comicPages":55,"albums":7,"photos":325,"posts":3,"videos":15,"games":5},"works":[{"id":"fushengsuiyue","title":"《浮生歲月：她與他的五個章節》","type":"小說","note":"喵叔原創小說《浮生歲月：她與他的五個章節》，從楔子到第十四章，沿著歲月與命運讀完一段完整故事。提供全文及章節目錄線上閱讀。","url":"books/fushengsuiyue/"},{"id":"liangzhongtiankong","title":"《兩種天空》","type":"小說","note":"喵叔原創小說《兩種天空》第一部十五章，從傘兵凌雲與外公的手札讀起，在記憶與天空之間尋找未曾說完的故事。全文線上閱讀。","url":"books/liangzhongtiankong/"},{"id":"liangzhongtiankong-part2","title":"《兩種天空 第二部：風中的回聲》","type":"小說","note":"喵叔小說《兩種天空》第二部〈風中的回聲〉，四十三章完整收錄。凌雲循著家書與戰友的聲音，追尋外公留下的往事。","url":"books/liangzhongtiankong-part2/"},{"id":"wuxiyue","title":"《烏溪月》","type":"小說","note":"喵叔原創小說《烏溪月》，楔子、十八章與尾聲完整收錄。從霧峰林家的舊手札走入烏溪畔的愛與離合。","url":"books/wuxiyue/"},{"id":"jiankangjie-tingquanyin","title":"《建康劫·聽泉引》","type":"小說","note":"喵叔小說《建康劫·聽泉引》，序章、三十七章與終章完整收錄。跟隨盲眼劍客衛宸穿越建康城烽火，走進守護與抉擇。","url":"books/jiankangjie-tingquanyin/"},{"id":"hiiro-setsugetsusho","title":"《緋色雪月抄》","type":"小說","note":"喵叔小說《緋色雪月抄》，四卷、序章、十二章與終章完整收錄。赤髮少年心太與芽依相遇，在亂世中走向守護與訣別。","url":"books/hiiro-setsugetsusho/"},{"id":"fengmen-yetan","title":"《風門夜譚》","type":"小說","note":"喵叔原創章回小說《風門夜譚》，引子與十回全文閱讀。書生柳毅逆行赴京，在風門屯遇見跨越人鬼界線的奇緣。","url":"books/fengmen-yetan/"},{"id":"alien-origin-sands","title":"《異形：起源之沙》","type":"小說","note":"喵叔小說《異形：起源之沙》，卷首語與十四章全文閱讀。尼羅河畔的永生實驗，喚醒金字塔深處的致命造物。","url":"books/alien-origin-sands/"},{"id":"chenshui-de-huhuan","title":"《沉睡的呼喚》","type":"小說","note":"喵叔原創小說《沉睡的呼喚》，卷首詩、序言、十一章與尾聲完整收錄。從臺北房租、泡麵與帳單走入夢境深處的失蹤之謎。","url":"books/chenshui-de-huhuan/"},{"id":"canzhao-xie-longqi","title":"《殘照寫龍契》","type":"小說","note":"喵叔原創長篇小說《殘照寫龍契》全十六章。從殘照下的蟬鳴走入龍脈、古墓與人心謎局，閱讀完整正文與章節目錄。","url":"books/canzhao-xie-longqi/"},{"id":"xia-ke-xing","title":"《俠客行》","type":"小說","note":"十四回・全書完結。姑蘇三場雪，三起命案牽出賑糧黑幕。顧長安持一柄黑鞘劍，追查顧家往事，也為無法替自己說話的人留下一條活路。","url":"books/xia-ke-xing/"},{"id":"the-bus-runs-tomorrow","title":"《全校最貴的學生》","type":"小說","note":"十二章・全書完結。全校最後一個六年級學生準備畢業那年，學校買了一匹馬。她原只想存錢離開，卻把都市家庭的體驗費換成山裡孩子的車資與床位。從老馬與樹苗，到一場墜馬事故，她必須面對善意的價錢，也面對自己曾經忽略的傷。","url":"books/the-bus-runs-tomorrow/"},{"id":"taipei-wumingye","title":"《臺北無名夜》","type":"小說","note":"全五十九章・全書完結。從〈點名人〉、〈七魄引〉、〈花葬臺北〉到〈放放看見的最後一夜〉與〈龍山寺凌晨四點的新聞〉，沈月棠與澟循著亡者的姓名，追查臺北夜裡被掩埋的往事。","url":"books/taipei-wumingye/"},{"id":"meiyue-shiwu","title":"《每月十五》","type":"小說","note":"一九六五年的臺北，許景衡在酒家遇見喬喬。家族、門第與各自的婚姻，使他們無法朝夕相守；每月十五的一頓飯，卻從年輕吃到白髮。四十八章完結，寫半世紀的相愛、慾望、牽掛與虧欠。","url":"books/meiyue-shiwu/"},{"id":"rain-stops-i-remain","title":"《雨停以後，我還在》","type":"小說","note":"十二章完結。許知微面對愛人與摯友的背叛，在台北的雨季裡慢慢找回自己的生活。","url":"books/rain-stops-i-remain/"},{"id":"xia-ke-xing-comic","title":"《俠客行》漫畫","type":"漫畫","note":"十四回・全書完結。姑蘇三場雪，三起命案牽出賑糧黑幕。顧長安持一柄黑鞘劍，追查顧家往事，也為無法替自己說話的人留下一條活路。","url":"books/xia-ke-xing/comic/"},{"id":"jiankangjie-tingquanyin-comic","title":"《建康劫·聽泉引》漫畫","type":"漫畫","note":"序章、三十七章與終章。從建康城的烽火走進盲眼劍客衛宸的守護與抉擇。","url":"books/jiankangjie-tingquanyin/comic/"},{"id":"long-leg-portraits","title":"長腿姐姐","type":"攝影","note":"一室暖燈打在窗框、深石和灰色織物上。她有時挨著檯面回頭，有時在沙發上鬆開肩膀，走到長廊又換成一身俐落的黑。沿著站姿與坐姿看下去，最耐看的往往是手剛停下的地方。","url":"gallery/#album-long-leg-portraits"},{"id":"november-photo-collection","title":"彈電吉它的女孩","type":"攝影","note":"白紗簾後的日光一直照進房間。她試過幾個和弦，把琴擱在膝頭，偶爾轉身翻書或捧杯歇息。沿著窗框看過去，琴聲停下的片刻也自有節奏。","url":"gallery/#album-november-photo-collection"},{"id":"street-daylight","title":"街角暖陽｜日常的光","type":"攝影","note":"便利商店門口有一片很好的日光。她從玻璃門旁走到石臺與長椅，撥一下頭髮，喝一口冰飲，再朝鏡頭笑。走了一圈回到門前，街角還是原來的街角，光已經走了一小段。","url":"gallery/#album-street-daylight"},{"id":"tiger-spirit","title":"虎虎生風","type":"攝影","note":"瀑布以下，溪光在樹蔭裡浮動。她與虎一同入鏡，光從髮梢挪到虎紋，有時又隔著水霧淡下去。六幅的距離慢慢拉近，水聲始終像在畫外。","url":"gallery/#album-tiger-spirit"},{"id":"emergence","title":"破繭而出","type":"攝影","note":"她先在畫框旁回頭，往前便是金色長廊。花影逐次落到衣上，摺痕也在轉身時清晰起來。走到亮處，華服的顏色已不只在燈下，也在她迎光站定的一刻。","url":"gallery/#album-emergence"},{"id":"city-night-portraits","title":"夜色街角","type":"攝影","note":"夜街裡，她把外套搭在肩邊，在石階、燈柱和欄杆旁停步。兩幅室內窗光把夜景隔開一會兒，接下來又回到路燈底下，看一張臉如何在不同距離迎向鏡頭。","url":"gallery/#album-city-night-portraits"},{"id":"chun-li-street","title":"春麗街影","type":"攝影","note":"雨水把街燈向下照了一遍，青藍旗袍便在路面與欄杆之間格外分明。她時而屈膝坐低，時而扶欄回望，也會在眼旁比個俏皮的手勢，讓長街的夜色有了不同步調。","url":"gallery/#album-chun-li-street"},{"id":"kawabata-bridge-20261011","title":"回首川端橋","type":"札記","note":"2026年10月11日，喵叔從川端橋的拱洞、綠色鋼梁走向新中正橋淺天空藍拱架，在河岸藝術與鐵馬行之間，回看新店溪兩岸的新舊交融。","url":"posts/kawabata-bridge-20261011/"},{"id":"taoyuan-design-expo-20261001","title":"把一點城市的光帶回家","type":"札記","note":"從拾伍石頭鍋物的午餐，到設計展、光流方舟與城市之鏡，把城市的光帶回自己的故事。","url":"posts/taoyuan-design-expo-20261001/"},{"id":"taipei-grand-trail-20260928","title":"把臺北走成一封給自己的信","type":"札記","note":"臺北大縱走第五段・減肥遊記。沿著山路看飛機、看城市，留住一片暮色，再好好吃頓飯。把這段路，寫給那個總說明天再出發的自己。","url":"posts/taipei-grand-trail-20260928/"}]};
